<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientTokenEndpointAuthMethodOptions;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientTokenEndpointAuthMethodAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTokenEndpointAuthMethodAccessor trait.
 *
 * Covers null default, string/VO assignment via withTokenEndpointAuthMethod,
 * getTokenEndpointAuthMethod/tokenEndpointAuthMethod accessors, and isTokenEndpointAuthMethodChanged with/without original.
 */
class TrustedClientTokenEndpointAuthMethodAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTokenEndpointAuthMethod creates a new instance with the TokenEndpointAuthMethod set
     * from a string value, and getTokenEndpointAuthMethod returns the primitive string.
     */
    public function testWithTokenEndpointAuthMethodFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthMethodAccessorUnitTest();

        // Act
        $result = $holder->withTokenEndpointAuthMethod(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC, $result->getTokenEndpointAuthMethod());
    }
    /**
     * Asserts that withtokenEndpointAuthMethod has access to the value object
     * from a string value, and getTokenEndpointAuthMethod returns the primitive string.
     */
    public function testWithTokenEndpointAuthMethodFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthMethodAccessorUnitTest();

        // Act
        $result = $holder->withTokenEndpointAuthMethod(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC, $result->tokenEndpointAuthMethod()->value());
    }
    public function testChangedTokenEndpointAuthMethod(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthMethodAccessorUnitTest()->withTokenEndpointAuthMethod(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC);
        $original = $holder->withTokenEndpointAuthMethod(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC);
        $same = $holder->withTokenEndpointAuthMethod(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC);
        $modified = $holder->withTokenEndpointAuthMethod(TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_POST);

        // Act
        $withSame = $original->isTokenEndpointAuthMethodChanged($same);
        $withDiferent = $original->isTokenEndpointAuthMethodChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientTokenEndpointAuthMethodAccessorUnitTest
{
    use TrustedClientTokenEndpointAuthMethodAccessor;
}
